import{_,o as t,a as i,b as a}from"./app.Zc0CUjTy.js";const l="/ascendc.github.io/assets/nz2nz_l0c2ub_dual_dst_c_api.liob8KIe.png",s="/ascendc.github.io/assets/nz2nd_l0c2ub_dual_dst_c_api.BoBjhnip.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"L0C Buffer到UB双目标模式","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/L0C_to_UB_dual_target_mode"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/L0C_to_UB_dual_target_mode.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/L0C_to_UB_dual_target_mode.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1789544578000}'),d={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/L0C_to_UB_dual_target_mode.md"};function r(c,e,o,n,p,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<div><article class="markdown-body"><h1>L0C Buffer到UB双目标模式</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>本特性仅适用于3510。同一AI Core内有一个Cube Core和两个Vector Core，当启用双目标模式控制时，L0C Buffer中的M×N矩阵将被分成两半，并同时分别写入两个Vector Core各自的Unified Buffer（UB）中，其中前半部分写入SUB BLOCK0，后半部分写入SUB BLOCK1。</p><ul><li>双目标模式（M维度）：按M维度拆分成形状为M / 2 * N的两个矩阵，分别写入两个UB。</li><li>双目标模式（N维度）：按N维度拆分成形状为M * N / 2的两个矩阵，分别写入两个UB。</li></ul><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li>双目标模式仅支持在L0C Buffer到UB通路，普通搬运模式（Nz2Nz）或Nz2ND搬运场景下使用，不支持随路功能场景。</li><li>按M维度拆分时M必须为2的倍数。</li><li>按N维度拆分时N须为32的倍数。</li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>在普通搬运模式下启用双目标模式如下图所示，分为按M维度拆分和按N维度拆分，按M维度拆分M必须为2的倍数，按N维度拆分N必须为32的倍数：</p><p>N方向切分：</p><ul><li>n_size = 32，表示源Nz矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li>m_size = 48，表示源Nz矩阵中待搬运矩阵在M方向上的大小48个元素。</li><li>src_stride = 64，表示源Nz矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个块Z排布矩阵的起始地址与第二个Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dst_stride = 64 * C0，表示目的Nz矩阵中相邻Z排布的起始地址偏移，该步长分别应用于每个UB内部，不是两个UB地址空间之间的距离。</li></ul><p>M方向切分：</p><ul><li>n_size = 32，表示源Nz矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li>m_size = 48，表示完整源矩阵M为48；拆分后每个UB收到24行，不能把拆分后行数作为源m_size。</li><li>src_stride = 64，表示源Nz矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个块Z排布矩阵的起始地址与第二个Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dst_stride = 40 * C0，表示目的Nz矩阵中相邻Z排布的起始地址偏移，即下图中UB0（或UB1）中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为40 * 16个元素。</li></ul><p><strong>图1</strong> Nz2Nz双目标搬运模式设置示意图</p><p><img src="'+l+'" alt></p><p>在Nz2ND模式下启用双目标模式如下图所示，分为按M维度拆分和按N维度拆分，按M维度拆分M必须为2的倍数，按N维度拆分N必须为32的倍数：</p><ul><li>nd_num = 2，表示源Nz矩阵的数目为2。图中红框区域为矩阵1，蓝框区域为矩阵2。</li><li>n_size = 32，表示源Nz矩阵（图中红框区域或蓝框区域）在N方向上的大小为32个元素。</li><li>m_size = 48，表示源Nz矩阵在M方向上的大小为48个元素。</li><li>src_stride = 64，表示源Nz矩阵中相邻Z排布的起始地址偏移，即下图红框区域中左侧浅色Z排布矩阵的起始地址与右侧深色Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dst_stride = 64，表示目的ND矩阵每一行中的元素个数为64。</li><li>src_nd_stride = 240 , 表示不同Nz矩阵起始地址之间的间隔为240 * C0_Size。</li><li>dst_nd_stride = 4096，表示目的相邻ND矩阵起始地址之间的偏移为4096个元素。</li></ul><p><strong>图2</strong> Nz2ND双目标搬出模式设置示意图</p><p><img src="'+s+'" alt></p><p>图中<code>nd_num</code>、<code>src_nd_stride</code>、<code>dst_nd_stride</code>分别对应<a href="../asc_set_l0c_copy_nz_para.html">asc_set_l0c_copy_nz_para</a>的<code>matrix_num</code>、<code>src_nz_matrix_stride</code>、<code>dst_matrix_stride</code>，本例取2、240、4096。<code>asc_copy_l0c2ub</code>通过<code>asc_dual_dst_mode::DUAL_DST_SPLIT_M</code>或<code>DUAL_DST_SPLIT_N</code>选择切分方向。Nz输出示例中的C0为16，<code>dst_stride</code>按目标元素计数。</p></article></div>',1)])])}const z=_(d,[["render",r]]);export{m as __pageData,z as default};
